#!/bin/bash
# compressed-image test: REAL zstd + zip archives (magic-only variants
# too), shimmed losetup/mount. xz cases live in test_imgxz.sh.
# Also covers the new RAM-disk (tmpfs) extraction preference:
#   * size known + fits  -> extract goes to the biggest-fit tmpfs (/dev/shm here)
#   * size huge (shim)   -> falls back to the image's own dir, no RAM note
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$HERE/.." && pwd)/pi_clean.sh
# shared rootfs fixture (regenerated by make_base_fix.sh when missing)
[[ -e /tmp/pi_clean_test/base_fix/etc/os-release ]] || bash "$HERE/make_base_fix.sh"
SHIM=/tmp/pi_clean_test/shim_loop
LOG=/tmp/pi_clean_test/shim_loop.log
ZSHIM=/tmp/pi_clean_test/shim_zhuge     # zstd shim that lies about the size
export SHIM_LOG="$LOG"
D=/tmp/pi_clean_test/xz
rm -rf "$D"; mkdir -p "$D"

# fixture payload + archives
tar -C /tmp/pi_clean_test -cf - base_fix 2>/dev/null > "$D/payload.img"
zstd -q -c "$D/payload.img" > "$D/image.zst"
cp "$D/image.zst" "$D/magic.img"                  # no .zst ext -> magic path
( cd "$D" && zip -q image.zip payload.img )
cp "$D/image.zip" "$D/magiczip.img"               # no .zip ext -> PK magic path
printf 'garbage not zstd' > "$D/broken.zst"
python3 - <<'EOF'
import zipfile
zipfile.ZipFile('/tmp/pi_clean_test/xz/empty.zip', 'w').close()
EOF

rm -rf "$SHIM"; mkdir -p "$SHIM"
STAGE=/tmp/pi_clean_test/dev_stage
rm -rf "$STAGE"; mkdir -p "$STAGE"
cp -a /tmp/pi_clean_test/base_fix/. "$STAGE/"
: > "$LOG"

cat > "$SHIM/losetup" <<'EOF'
#!/bin/bash
echo "losetup $*" >> "${SHIM_LOG:?}"
case $* in -d*) exit 0 ;; esac
[[ -n ${SHIM_FAILALL:-} ]] && exit 1
echo /dev/loop0
EOF
cat > "$SHIM/mount" <<'EOF'
#!/bin/bash
dev=$3; mp=$4
[[ $dev == /dev/loop0 ]] || exit 32
cp -a ${SHIM_STAGE}/. "$mp/"
exit 0
EOF
# emulate a REAL umount: the "filesystem" (the staged content the sim
# `mount` copied into the mount point) comes off; the mount-point dir
# itself stays (as with a real umount) so the script's rmdir succeeds
cat > "$SHIM/umount" <<'EOF'
#!/bin/bash
mp=${1:-}
# GNU rm refuses "dir/." — find -delete empties the dir, keeps the dir itself
[[ -n $mp && -d $mp ]] && find "$mp" -mindepth 1 -delete 2>/dev/null
exit 0
EOF
export SHIM_STAGE="$STAGE"
chmod +x "$SHIM/losetup" "$SHIM/mount" "$SHIM/umount"

# zstd that reports a huge decompressed size (gate must reject the RAM disk)
rm -rf "$ZSHIM"; mkdir -p "$ZSHIM"
cat > "$ZSHIM/zstd" <<'EOF'
#!/bin/bash
if [[ $1 == -l ]]; then
    printf 'Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n'
    printf '     1      0      5.47 KiB      9999 TiB  8172.255  XXH64  image.zst\n'
    exit 0
fi
exec /usr/bin/zstd "$@"
EOF
chmod +x "$ZSHIM/zstd"

num()  { PATH="$SHIM:$PATH" bash "$P" "$1" -t 2>/dev/null; }
note() { PATH="$SHIM:$PATH" bash "$P" "$1" -t 2>&1 >/dev/null; }
showpath() { grep -o 'show [^ ]*' "$LOG" | tail -n1 | sed 's/.*show //'; }

noextracts() {
    local l; l=$(ls /dev/shm/pi_clean.* "$D"/pi_clean.* /tmp/pi_clean.* 2>/dev/null)
    if [[ -n $l ]]; then echo "FAIL: extract left behind: $l"; return 1; fi
    echo "PASS: no extract left behind"
}

echo F=zstd
[[ "$(num "$D/image.zst")" == "2097162" ]] && echo "PASS: -t on .zst" || echo "FAIL: .zst"
[[ "$(note "$D/image.zst")" == *"extracting to RAM: "* ]] && echo "PASS: RAM note (zst)" || echo "FAIL: no RAM note (zst): $(note "$D/image.zst")"
[[ "$(note "$D/image.zst")" == *"decompressing"*"can take a while"* && "$(note "$D/image.zst")" == *"extracted to "* ]] \
    && echo "PASS: extraction announced (zst)" || echo "FAIL: no extraction announcement (zst)"
[[ "$(showpath)" == /dev/shm/pi_clean.* ]] && echo "PASS: extract went to the RAM disk (zst)" || echo "FAIL: extract path: $(showpath)"
noextracts
[[ "$(num "$D/magic.img")" == "2097162" ]] && echo "PASS: -t on zstd-by-magic (no ext)" || echo "FAIL: zst magic"
noextracts

echo G=zip
[[ "$(num "$D/image.zip")" == "2097162" ]] && echo "PASS: -t on .zip" || echo "FAIL: .zip"
[[ "$(note "$D/image.zip")" == *"extracting to RAM: "* ]] && echo "PASS: RAM note (zip)" || echo "FAIL: no RAM note (zip): $(note "$D/image.zip")"
[[ "$(note "$D/image.zip")" == *"decompressing"*"can take a while"* && "$(note "$D/image.zip")" == *"extracted to "* ]] \
    && echo "PASS: extraction announced (zip)" || echo "FAIL: no extraction announcement (zip)"
[[ "$(showpath)" == /dev/shm/pi_clean.* ]] && echo "PASS: extract went to the RAM disk (zip)" || echo "FAIL: extract path: $(showpath)"
noextracts
[[ "$(num "$D/magiczip.img")" == "2097162" ]] && echo "PASS: -t on zip-by-magic (PK, no ext)" || echo "FAIL: zip magic"
noextracts

echo H=malformed
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/broken.zst" -t 2>&1); rc=$?
[[ $rc == 2 && $out == *"extracting"*"failed"* ]] && echo "PASS: corrupt .zst -> clean failure" || echo "FAIL: corrupt zst (rc=$rc): $out"
noextracts
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/empty.zip" -t 2>&1); rc=$?
[[ $rc == 2 && $out == *"no entry found in the zip"* ]] && echo "PASS: empty zip -> no-entry failure" || echo "FAIL: empty zip (rc=$rc): $out"
noextracts

echo I=sizes-too-big-for-RAM
[[ "$(num "$D/image.zst")" == "2097162" ]] || { :; }
n2=$(PATH="$ZSHIM:$SHIM:$PATH" bash "$P" "$D/image.zst" -t 2>&1 >/dev/null); rc=$?
[[ $rc == 0 && $n2 != *"extracting to RAM"* ]] && echo "PASS: huge-size archive NOT put in RAM" || echo "FAIL: big-size ran into RAM: $n2"
[[ "$(showpath)" == "$D"/pi_clean.* ]] && echo "PASS: fell back to the image's own dir" || echo "FAIL: fallback path: $(showpath)"
noextracts

echo J=cleanup-on-attach-failure
out=$(env SHIM_FAILALL=1 PATH="$SHIM:$PATH" bash "$P" "$D/image.zst" -t 2>&1); rc=$?
[[ $rc == 2 && $out == *"cannot attach"* ]] && echo "PASS: attach failure with .zst" || echo "FAIL: attach-fail zst (rc=$rc): $out"
noextracts
grep -q '^losetup -d /dev/loop0$' "$LOG" && echo "PASS: loop detached on exit" || { echo "FAIL: no detach:"; cat "$LOG"; }
left=$(ls -d /run/pi_clean.* /tmp/pi_clean.* 2>/dev/null)
[[ -z $left ]] && echo "PASS: no leftover mount points" || { echo "shim leftovers (expected): $left"; rm -rf $left; }

echo K=clean-refused-for-compressed
cs0=$(cksum "$D/image.zst"); csz=$(cksum "$D/image.zip")
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/image.zst" -c 2>&1); rc=$?
[[ $rc == 2 && $out == *"-c is not available"*"compressed images"* ]] \
    && echo "PASS (rc=$rc): -c on a .zst is refused (exit 2)" \
    || { echo "FAIL (rc=$rc): -c .zst"; printf '%s\n' "$out" | head -8; }
[[ $out == *"stay untouched"* && $out == *"Run it without -c"* ]] \
    && echo "PASS: the refusal explains why (throwaway extract; see the report without -c)" \
    || echo "FAIL: refusal message incomplete: ${out:0:200}"
noextracts
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/image.zst" -c -y 2>&1); rc=$?
[[ $rc == 2 ]] && echo "PASS (rc=$rc): -c -y on a .zst is still refused" || echo "FAIL: -c -y .zst rc=$rc"
[[ $(cksum "$D/image.zst") == "$cs0" && $(cksum "$D/image.zip") == "$csz" ]] \
    && echo "PASS: the archives are byte-identical after the -c attempts" \
    || echo "FAIL: archives mutated by the refused -c"
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/image.zip" -c 2>&1); rc=$?
[[ $rc == 2 && $out == *"-c is not available"*"compressed images"* ]] \
    && echo "PASS (rc=$rc): -c on a .zip is refused (exit 2)" \
    || { echo "FAIL (rc=$rc): -c .zip"; printf '%s\n' "$out" | head -8; }
noextracts
